package io.github.apace100.origins;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import io.github.apace100.apoli.Apoli;
import io.github.apace100.apoli.power.PowerType;
import io.github.apace100.apoli.power.PowerTypes;
import io.github.apace100.apoli.util.IdentifierAlias;
import io.github.apace100.calio.resource.OrderedResourceListenerInitializer;
import io.github.apace100.calio.resource.OrderedResourceListenerManager;
import io.github.apace100.origins.badge.BadgeManager;
import io.github.apace100.origins.command.OriginCommand;
import io.github.apace100.origins.networking.ModPacketsC2S;
import io.github.apace100.origins.origin.Origin;
import io.github.apace100.origins.origin.OriginLayers;
import io.github.apace100.origins.origin.OriginManager;
import io.github.apace100.origins.power.OriginsEntityConditions;
import io.github.apace100.origins.power.OriginsPowerTypes;
import io.github.apace100.origins.registry.*;
import io.github.apace100.origins.util.ChoseOriginCriterion;
import io.github.apace100.origins.util.OriginLootCondition;
import io.github.apace100.origins.util.OriginsConfigSerializer;
import io.github.apace100.origins.util.OriginsJsonConfigSerializer;
import me.shedaniel.autoconfig.AutoConfig;
import me.shedaniel.autoconfig.ConfigData;
import me.shedaniel.autoconfig.annotation.Config;
import me.shedaniel.autoconfig.serializer.ConfigSerializer;
import net.fabricmc.api.ModInitializer;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.fabricmc.fabric.api.itemgroup.v1.ItemGroupEvents;
import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;
import net.fabricmc.fabric.api.resource.IdentifiableResourceReloadListener;
import net.fabricmc.loader.api.FabricLoader;
import net.minecraft.advancement.criterion.Criteria;
import net.minecraft.item.ItemGroups;
import net.minecraft.registry.Registries;
import net.minecraft.registry.Registry;
import net.minecraft.resource.ResourceType;
import net.minecraft.util.Identifier;
import net.minecraft.util.JsonHelper;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class Origins implements ModInitializer, OrderedResourceListenerInitializer {

	public static final String MODID = "origins";
	public static String VERSION = "";
	public static int[] SEMVER;
	public static final Logger LOGGER = LogManager.getLogger(Origins.class);

	public static ServerConfig config;
	private static ConfigSerializer<ServerConfig> configSerializer;

	@Override
	public void onInitialize() {
		FabricLoader.getInstance().getModContainer(MODID).ifPresent(modContainer -> {
			VERSION = modContainer.getMetadata().getVersion().getFriendlyString();
			if(VERSION.contains("+")) {
				VERSION = VERSION.split("\\+")[0];
			}
			if(VERSION.contains("-")) {
				VERSION = VERSION.split("-")[0];
			}
			String[] splitVersion = VERSION.split("\\.");
			SEMVER = new int[splitVersion.length];
			for(int i = 0; i < SEMVER.length; i++) {
				SEMVER[i] = Integer.parseInt(splitVersion[i]);
			}
		});
		LOGGER.info("Origins " + VERSION + " is initializing. Have fun!");

		AutoConfig.register(ServerConfig.class,
			(definition, configClass) -> {
				configSerializer = new OriginsJsonConfigSerializer<>(definition, configClass,
					new OriginsConfigSerializer<>(definition, configClass));
				return configSerializer;
			});
		config = AutoConfig.getConfigHolder(ServerConfig.class).getConfig();

		IdentifierAlias.addNamespaceAlias(MODID, "apoli");

		OriginsPowerTypes.register();
		OriginsEntityConditions.register();

		ModBlocks.register();
		ModItems.register();
		ModTags.register();
		ModPacketsC2S.register();
		ModEnchantments.register();
		ModEntities.register();
		ModLoot.registerLootTables();
		ModComponents.register();
		Origin.init();

		CommandRegistrationCallback.EVENT.register((dispatcher, registryAccess, environment) -> OriginCommand.register(dispatcher));
		ItemGroupEvents.modifyEntriesEvent(ItemGroups.TOOLS).register((content) -> content.add(ModItems.ORB_OF_ORIGIN));

		Criteria.register(ChoseOriginCriterion.ID.toString(), ChoseOriginCriterion.INSTANCE);
		Registry.register(Registries.LOOT_CONDITION_TYPE, identifier("origin"), OriginLootCondition.TYPE);

		ServerPlayConnectionEvents.DISCONNECT.register((handler, server) -> ModComponents.ORIGIN.get(handler.player).selectingOrigin(false));
	}

	public static void serializeConfig() {
		try {
			configSerializer.serialize(config);
		} catch (ConfigSerializer.SerializationException e) {
			Origins.LOGGER.error("Failed serialization of config file: " + e.getMessage());
		}
	}

	public static Identifier identifier(String path) {
		return new Identifier(Origins.MODID, path);
	}

	@Override
	public void registerResourceListeners(OrderedResourceListenerManager manager) {
		Identifier powerData = Apoli.identifier("powers");
		Identifier originData = Origins.identifier("origins");

		OriginManager originLoader = new OriginManager();
		manager.register(ResourceType.SERVER_DATA, originLoader).after(powerData).complete();
		manager.register(ResourceType.SERVER_DATA, new OriginLayers()).after(originData).complete();

		BadgeManager.init();

		IdentifiableResourceReloadListener badgeLoader = BadgeManager.REGISTRY.getLoader();
		manager.register(ResourceType.SERVER_DATA, badgeLoader).before(powerData).complete();
		PowerTypes.DEPENDENCIES.add(badgeLoader.getFabricId());
	}

	@Config(name = Origins.MODID + "_server")
	public static class ServerConfig implements ConfigData {

		public boolean performVersionCheck = true;

		public JsonObject origins = new JsonObject();

		public boolean isOriginDisabled(Identifier originId) {
			String idString = originId.toString();
			if(!origins.has(idString)) {
				return false;
			}
			JsonElement element = origins.get(idString);
			if(element instanceof JsonObject jsonObject) {
				return !JsonHelper.getBoolean(jsonObject, "enabled", true);
			}
			return false;
		}

		public boolean isPowerDisabled(Identifier originId, Identifier powerId) {
			String originIdString = originId.toString();
			if(!origins.has(originIdString)) {
				return false;
			}
			String powerIdString = powerId.toString();
			JsonElement element = origins.get(originIdString);
			if(element instanceof JsonObject jsonObject) {
				return !JsonHelper.getBoolean(jsonObject, powerIdString, true);
			}
			return false;
		}

		public boolean addToConfig(Origin origin) {
			boolean changed = false;
			String originIdString = origin.getIdentifier().toString();
			JsonObject originObj;
			if(!origins.has(originIdString) || !(origins.get(originIdString) instanceof JsonObject)) {
				originObj = new JsonObject();
				origins.add(originIdString, originObj);
				changed = true;
			} else {
				originObj = (JsonObject) origins.get(originIdString);
			}
			if(!originObj.has("enabled") || !(originObj.get("enabled") instanceof JsonPrimitive)) {
				originObj.addProperty("enabled", Boolean.TRUE);
				changed = true;
			}
			for(PowerType<?> power : origin.getPowerTypes()) {
				String powerIdString = power.getIdentifier().toString();
				if(!originObj.has(powerIdString) || !(originObj.get(powerIdString) instanceof JsonPrimitive)) {
					originObj.addProperty(powerIdString, Boolean.TRUE);
					changed = true;
				}
			}
			return changed;
		}
	}
}

package io.github.apace100.origins.component;

import dev.onyxstudios.cca.api.v3.component.sync.AutoSyncedComponent;
import dev.onyxstudios.cca.api.v3.component.tick.CommonTickingComponent;
import io.github.apace100.apoli.component.PowerHolderComponent;
import io.github.apace100.apoli.power.ModifyPlayerSpawnPower;
import io.github.apace100.apoli.power.Power;
import io.github.apace100.apoli.power.PowerType;
import io.github.apace100.origins.origin.Origin;
import io.github.apace100.origins.origin.OriginLayer;
import io.github.apace100.origins.origin.OriginLayers;
import io.github.apace100.origins.origin.OriginRegistry;
import io.github.apace100.origins.power.OriginsCallbackPower;
import io.github.apace100.origins.registry.ModComponents;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.util.Identifier;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

public interface OriginComponent extends AutoSyncedComponent, CommonTickingComponent {

	Map<OriginLayer, Origin> getOrigins();
	Origin getOrigin(OriginLayer layer);

	boolean hasSelectionInvulnerability();
	boolean isSelectingOrigin();
	boolean hasOrigin(OriginLayer layer);
	boolean hasAllOrigins();
	boolean hadOriginBefore();

	void selectingOrigin(boolean selectingOrigin);
	void removeLayer(OriginLayer layer);
	void setOrigin(OriginLayer layer, Origin origin);
	void sync();

	@Deprecated(forRemoval = true)
	void onPowersRead();

	static void sync(PlayerEntity player) {
		ModComponents.ORIGIN.sync(player);
		PowerHolderComponent.KEY.sync(player);
	}

	static void onChosen(PlayerEntity player, boolean hadOriginBefore) {
		if(!hadOriginBefore) {
			PowerHolderComponent.getPowers(player, ModifyPlayerSpawnPower.class).forEach(ModifyPlayerSpawnPower::teleportToModifiedSpawn);
		}
		PowerHolderComponent.getPowers(player, OriginsCallbackPower.class).forEach(p -> p.onChosen(hadOriginBefore));
	}

	static void partialOnChosen(PlayerEntity player, boolean hadOriginBefore, Origin origin) {
		PowerHolderComponent powerHolder = PowerHolderComponent.KEY.get(player);
		for(PowerType<?> powerType : powerHolder.getPowersFromSource(origin.getIdentifier())) {
			Power p = powerHolder.getPower(powerType);
			if(p instanceof ModifyPlayerSpawnPower && !hadOriginBefore) {
				((ModifyPlayerSpawnPower)p).teleportToModifiedSpawn();
			} else
			if(p instanceof OriginsCallbackPower) {
				((OriginsCallbackPower)p).onChosen(hadOriginBefore);
			}
		}
	}

	default boolean checkAutoChoosingLayers(PlayerEntity player, boolean includeDefaults) {

		List<OriginLayer> layers = new ArrayList<>();
		boolean choseOneAutomatically = false;

		OriginLayers.getLayers()
			.stream()
			.filter(OriginLayer::isEnabled)
			.forEach(layers::add);

		Collections.sort(layers);
		for (OriginLayer layer : layers) {

			if (!layer.isEnabled() || hasOrigin(layer)) {
				continue;
			}

			if (includeDefaults && layer.hasDefaultOrigin()) {

				setOrigin(layer, OriginRegistry.get(layer.getDefaultOrigin()));
				choseOneAutomatically = true;

			} else if (layer.getOriginOptionCount(player) == 1 && layer.shouldAutoChoose()) {

				List<Origin> origins = layer.getOrigins(player)
					.stream()
					.map(OriginRegistry::get)
					.filter(Origin::isChoosable)
					.toList();

				if (!origins.isEmpty()) {

					setOrigin(layer, origins.get(0));
					choseOneAutomatically = true;

				} else if (layer.isRandomAllowed() && !layer.getRandomOrigins(player).isEmpty()) {

					List<Identifier> randomOriginIds = layer.getRandomOrigins(player);
					int randomOriginIndex = player.getRandom().nextInt(randomOriginIds.size());

					setOrigin(layer, OriginRegistry.get(randomOriginIds.get(randomOriginIndex)));
					choseOneAutomatically = true;

				}

			}

		}

		return choseOneAutomatically;

	}

}

package io.github.apace100.origins.component;

import io.github.apace100.apoli.component.PowerHolderComponent;
import io.github.apace100.apoli.power.PowerType;
import io.github.apace100.apoli.power.PowerTypeRegistry;
import io.github.apace100.origins.Origins;
import io.github.apace100.origins.origin.Origin;
import io.github.apace100.origins.origin.OriginLayer;
import io.github.apace100.origins.origin.OriginLayers;
import io.github.apace100.origins.origin.OriginRegistry;
import io.github.apace100.origins.util.ChoseOriginCriterion;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.nbt.NbtList;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;
import org.jetbrains.annotations.NotNull;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class PlayerOriginComponent implements OriginComponent {

    private final Map<OriginLayer, Origin> origins = new ConcurrentHashMap<>();
    private final PlayerEntity player;

    private boolean selectingOrigin = false;
    private boolean hadOriginBefore = false;

    private int invulnerabilityTicks = 0;

    public PlayerOriginComponent(PlayerEntity player) {
        this.player = player;
    }

    @Override
    public boolean hasSelectionInvulnerability() {
        return invulnerabilityTicks > 0;
    }

    @Override
    public boolean isSelectingOrigin() {
        return selectingOrigin;
    }

    @Override
    public void selectingOrigin(boolean selectingOrigin) {
        this.selectingOrigin = selectingOrigin;
        if (selectingOrigin) {
            invulnerabilityTicks = 60;
        }
    }

    @Override
    public boolean hasAllOrigins() {
        return OriginLayers.getLayers()
            .stream()
            .allMatch(layer -> !layer.isEnabled()
                            || (layer.getOrigins().isEmpty() || layer.getOriginOptionCount(player) == 0)
                            || hasOrigin(layer));
    }

    @Override
    public Map<OriginLayer, Origin> getOrigins() {
        return origins;
    }

    @Override
    public boolean hasOrigin(OriginLayer layer) {
        return origins.containsKey(layer)
            && origins.get(layer) != Origin.EMPTY;
    }

    @Override
    public Origin getOrigin(OriginLayer layer) {
        return origins.get(layer);
    }

    @Override
    public boolean hadOriginBefore() {
        return hadOriginBefore;
    }

    @Override
    public void removeLayer(OriginLayer layer) {

        Origin oldOrigin = getOrigin(layer);
        if (oldOrigin != null) {
            PowerHolderComponent.KEY.get(player).removeAllPowersFromSource(oldOrigin.getIdentifier());
        }

        origins.remove(layer);

    }

    @Override
    public void setOrigin(OriginLayer layer, Origin origin) {

        Origin oldOrigin = getOrigin(layer);
        if (origin == oldOrigin) {
            return;
        }

        PowerHolderComponent powerComponent = PowerHolderComponent.KEY.get(player);
        if (oldOrigin != null) {

            if (!oldOrigin.getIdentifier().equals(origin.getIdentifier())) {
                powerComponent.removeAllPowersFromSource(oldOrigin.getIdentifier());
            }

            else if (!oldOrigin.toJson().equals(origin.toJson())) {
                revokeRemovedPowers(origin, powerComponent);
            }

        }

        grantPowersFromOrigin(origin, powerComponent);
        this.origins.put(layer, origin);

        if (this.hasAllOrigins()) {
            this.hadOriginBefore = true;
        }

        if (player instanceof ServerPlayerEntity spe) {
            ChoseOriginCriterion.INSTANCE.trigger(spe, origin);
        }

    }

    private void grantPowersFromOrigin(Origin origin, PowerHolderComponent powerComponent) {
        Identifier sourceId = origin.getIdentifier();
        origin.getPowerTypes()
            .stream()
            .filter(pt -> !powerComponent.hasPower(pt, sourceId))
            .forEach(pt -> powerComponent.addPower(pt, sourceId));
    }

    private void revokeRemovedPowers(Origin origin, PowerHolderComponent powerComponent) {
        Identifier sourceId = origin.getIdentifier();
        powerComponent.getPowersFromSource(sourceId)
            .stream()
            .filter(pt -> !origin.hasPowerType(pt))
            .forEach(pt -> powerComponent.removePower(pt, sourceId));
    }

    @Override
    public void tick() {
        if (!selectingOrigin && invulnerabilityTicks > 0) {
            invulnerabilityTicks--;
        }
    }

    @Override
    public void readFromNbt(@NotNull NbtCompound compoundTag) {

        if (player == null) {
            Origins.LOGGER.error("Player was null in PlayerOriginComponent#fromTag! This is not supposed to happen D:");
            return;
        }

        PowerHolderComponent powerComponent = PowerHolderComponent.KEY.get(player);
        origins.clear();

        //  Migrate origin data from old versions
        if (compoundTag.contains("Origin")) {
            try {

                OriginLayer defaultOriginLayer = OriginLayers.getLayer(Origins.identifier("origin"));
                origins.put(defaultOriginLayer, OriginRegistry.get(new Identifier(compoundTag.getString("Origin"))));

            } catch (Exception ignored) {
                Origins.LOGGER.warn("Player {} had old origin which could not be migrated: {}", player.getName().getString(), compoundTag.getString("Origin"));
            }
        } else {

            NbtList originLayersNbt = compoundTag.getList("OriginLayers", NbtElement.COMPOUND_TYPE);
            for (int i = 0; i < originLayersNbt.size(); i++) {

                NbtCompound originLayerNbt = originLayersNbt.getCompound(i);
                try {

                    Identifier layerId = new Identifier(originLayerNbt.getString("Layer"));
                    Identifier originId = new Identifier(originLayerNbt.getString("Origin"));

                    OriginLayer layer = OriginLayers.getLayer(layerId);
                    Origin origin = OriginRegistry.get(originId);

                    origins.put(layer, origin);

                    if (layer.contains(origin) || origin.isSpecial()) {
                        continue;
                    }

                    Origins.LOGGER.warn("Origin \"{}\" is not in origin layer \"{}\" and is not considered special, but was found on player {}!", originId, layerId, player.getName().getString());

                    powerComponent.removeAllPowersFromSource(originId);
                    origins.put(layer, Origin.EMPTY);

                } catch (Exception e) {
                    Origins.LOGGER.error("There was a problem trying to read origin NBT data of player {}: {}", player.getName().getString(), e.getMessage());
                }

            }

        }

        selectingOrigin = compoundTag.getBoolean("SelectingOrigin");
        hadOriginBefore = compoundTag.getBoolean("HadOriginBefore");

        if (player.getWorld().isClient) {
            return;
        }

        for (Origin origin : origins.values()) {
            //  Grant powers only if the player doesn't have them yet from the specific Origin source.
            //  Needed in case the origin was set before the update to Apoli happened.
            grantPowersFromOrigin(origin, powerComponent);
        }

        for (Origin origin : origins.values()) {
            revokeRemovedPowers(origin, powerComponent);
        }

        //  Compatibility with old worlds. Load power data from Origins' NBT, whereas in new versions, power data is
        //  stored in Apoli's NBT
        if (!compoundTag.contains("Powers")) {
            return;
        }

        NbtList legacyPowersNbt = compoundTag.getList("Powers", NbtElement.COMPOUND_TYPE);
        for (int i = 0; i < legacyPowersNbt.size(); i++) {

            NbtCompound legacyPowerNbt = legacyPowersNbt.getCompound(i);
            String legacyPowerString = legacyPowerNbt.getString("Type");

            try {

                Identifier legacyPowerId = new Identifier(legacyPowerString);
                PowerType<?> legacyPowerType = PowerTypeRegistry.get(legacyPowerId);

                if (!powerComponent.hasPower(legacyPowerType)) {
                    continue;
                }

                try {
                    NbtElement legacyPowerData = legacyPowerNbt.get("Data");
                    powerComponent.getPower(legacyPowerType).fromTag(legacyPowerData);
                } catch (ClassCastException e) {
                    //  Occurs when the power was overridden by a data pack since last world load
                    //  where the overridden power now uses different data classes
                    Origins.LOGGER.warn("Data type of power \"{}\" changed, skipping data for that power on entity {}", legacyPowerId, player.getName().getString());
                }


            } catch (IllegalArgumentException e) {
                Origins.LOGGER.warn("Power data of unregistered power \"{}\" found on player {}, skipping...", legacyPowerString, player.getName().getString());
            }

        }

    }

    @Override
    public void onPowersRead() {
        // NO-OP
    }

    @Override
    public void writeToNbt(@NotNull NbtCompound compoundTag) {

        NbtList originLayersNbt = new NbtList();
        origins.forEach((layer, origin) -> {

            NbtCompound originLayerNbt = new NbtCompound();

            originLayerNbt.putString("Layer", layer.getIdentifier().toString());
            originLayerNbt.putString("Origin", origin.getIdentifier().toString());

            originLayersNbt.add(originLayerNbt);

        });

        compoundTag.put("OriginLayers", originLayersNbt);
        compoundTag.putBoolean("SelectingOrigin", selectingOrigin);
        compoundTag.putBoolean("HadOriginBefore", hadOriginBefore);

    }

    @Override
    public void sync() {
        OriginComponent.sync(this.player);
    }

}

package io.github.apace100.origins.mixin;

import com.llamalad7.mixinextras.injector.ModifyReturnValue;
import io.github.apace100.origins.component.OriginComponent;
import io.github.apace100.origins.registry.ModComponents;
import net.minecraft.entity.Entity;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;

@Mixin(Entity.class)
public abstract class SelectionInvulnerabilityMixin {

    @ModifyReturnValue(method = "isInvulnerableTo", at = @At("RETURN"))
    private boolean origin$makeOriginInvulnerable(boolean original) {
        return original || ModComponents.ORIGIN.maybeGet(this).map(OriginComponent::hasSelectionInvulnerability).orElse(false);
    }

}

package io.github.apace100.origins.networking;

import io.github.apace100.origins.Origins;
import io.github.apace100.origins.component.OriginComponent;
import io.github.apace100.origins.networking.packet.VersionHandshakePacket;
import io.github.apace100.origins.networking.packet.c2s.ChooseOriginC2SPacket;
import io.github.apace100.origins.networking.packet.c2s.ChooseRandomOriginC2SPacket;
import io.github.apace100.origins.networking.packet.s2c.ConfirmOriginS2CPacket;
import io.github.apace100.origins.networking.task.VersionHandshakeTask;
import io.github.apace100.origins.origin.Origin;
import io.github.apace100.origins.origin.OriginLayer;
import io.github.apace100.origins.origin.OriginLayers;
import io.github.apace100.origins.origin.OriginRegistry;
import io.github.apace100.origins.registry.ModComponents;
import net.fabricmc.fabric.api.networking.v1.PacketSender;
import net.fabricmc.fabric.api.networking.v1.ServerConfigurationConnectionEvents;
import net.fabricmc.fabric.api.networking.v1.ServerConfigurationNetworking;
import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.network.ServerConfigurationNetworkHandler;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.text.Text;
import net.minecraft.util.Identifier;

import java.util.List;

@SuppressWarnings("UnstableApiUsage")
public class ModPacketsC2S {

    public static void register() {

        if (Origins.config.performVersionCheck) {
            ServerConfigurationConnectionEvents.CONFIGURE.register(ModPacketsC2S::handshake);
            ServerConfigurationNetworking.registerGlobalReceiver(VersionHandshakePacket.TYPE, ModPacketsC2S::handleHandshakeReply);
        }

        ServerPlayNetworking.registerGlobalReceiver(ChooseOriginC2SPacket.TYPE, ModPacketsC2S::onChooseOrigin);
        ServerPlayNetworking.registerGlobalReceiver(ChooseRandomOriginC2SPacket.TYPE, ModPacketsC2S::chooseRandomOrigin);

    }

    private static void onChooseOrigin(ChooseOriginC2SPacket packet, ServerPlayerEntity player, PacketSender responseSender) {

        OriginComponent component = ModComponents.ORIGIN.get(player);
        OriginLayer layer = OriginLayers.getLayer(packet.layerId());

        if (component.hasAllOrigins() && component.hasOrigin(layer)) {
            Origins.LOGGER.warn("Player {} tried to choose origin for layer \"{}\" while having one already.", player.getName().getString(), packet.layerId());
            return;
        }

        Origin origin = OriginRegistry.get(packet.originId());
        if (!(origin.isChoosable() || layer.contains(origin, player))) {
            Origins.LOGGER.warn("Player {} tried to choose unchoosable origin \"{}\" from layer \"{}\"!", player.getName().getString(), packet.originId(), packet.layerId());
            component.setOrigin(layer, Origin.EMPTY);
        } else {

            boolean hadOriginBefore = component.hadOriginBefore();
            boolean hadAllOrigins = component.hasAllOrigins();

            component.setOrigin(layer, origin);
            component.checkAutoChoosingLayers(player, false);

            component.sync();

            if (component.hasAllOrigins() && !hadAllOrigins) {
                OriginComponent.onChosen(player, hadOriginBefore);
            }

            Origins.LOGGER.info("Player {} chose origin \"{}\" for layer \"{}\"", player.getName().getString(), packet.originId(), packet.layerId());

        }

        confirmOrigin(player, layer, component.getOrigin(layer));

        component.selectingOrigin(false);
        component.sync();

    }

    private static void chooseRandomOrigin(ChooseRandomOriginC2SPacket packet, ServerPlayerEntity player, PacketSender responseSender) {

        OriginComponent component = ModComponents.ORIGIN.get(player);
        OriginLayer layer = OriginLayers.getLayer(packet.layerId());

        if (component.hasAllOrigins() && component.hasOrigin(layer)) {
            Origins.LOGGER.warn("Player {} tried to choose origin for layer \"{}\" while having one already.", player.getName().getString(), packet.layerId());
            return;
        }

        List<Identifier> randomOriginIds = layer.getRandomOrigins(player);
        if (!layer.isRandomAllowed() || randomOriginIds.isEmpty()) {
            Origins.LOGGER.warn("Player {} tried to choose a random origin for layer \"{}\", which is not allowed!", player.getName().getString(), packet.layerId());
            component.setOrigin(layer, Origin.EMPTY);
        } else {

            Identifier randomOriginId = randomOriginIds.get(player.getRandom().nextInt(randomOriginIds.size()));
            Origin origin = OriginRegistry.get(randomOriginId);

            boolean hadOriginBefore = component.hadOriginBefore();
            boolean hadAllOrigins = component.hasAllOrigins();

            component.setOrigin(layer, origin);
            component.checkAutoChoosingLayers(player, false);

            component.sync();
            if (component.hasAllOrigins() && !hadAllOrigins) {
                OriginComponent.onChosen(player, hadOriginBefore);
            }

            Origins.LOGGER.info("Player {} was randomly assigned the following origin: {}", player.getName().getString(), randomOriginId);

        }

        confirmOrigin(player, layer, component.getOrigin(layer));

        component.selectingOrigin(false);
        component.sync();

    }

    private static void handleHandshakeReply(VersionHandshakePacket packet, ServerConfigurationNetworkHandler handler, PacketSender responseSender) {

        boolean mismatch = packet.semver().length != Origins.SEMVER.length;
        for (int i = 0; !mismatch && i < packet.semver().length - 1; i++) {

            if (packet.semver()[i] != Origins.SEMVER[i]) {
                mismatch = true;
                break;
            }

        }

        if (!mismatch) {
            handler.completeTask(VersionHandshakeTask.KEY);
            return;
        }

        StringBuilder semverString = new StringBuilder();
        String separator = "";

        for (int i : packet.semver()) {
            semverString.append(separator).append(i);
            separator = ".";
        }

        handler.disconnect(Text.translatable("origins.gui.version_mismatch", Origins.VERSION, semverString));

    }

    private static void handshake(ServerConfigurationNetworkHandler handler, MinecraftServer server) {

        if (ServerConfigurationNetworking.canSend(handler, VersionHandshakePacket.TYPE)) {
            handler.addTask(new VersionHandshakeTask(Origins.SEMVER));
            return;
        }

        handler.disconnect(Text.of("This server requires you to install the Origins mod (v " + Origins.VERSION + ") to play."));

    }

    private static void confirmOrigin(ServerPlayerEntity player, OriginLayer layer, Origin origin) {
        ServerPlayNetworking.send(player, new ConfirmOriginS2CPacket(layer.getIdentifier(), origin.getIdentifier()));
    }

}

package io.github.apace100.origins.origin;

