        return conditionedOrigins
            .stream()
            .filter(co -> playerEntity == null || co.isConditionFulfilled(playerEntity))
            .flatMap(co -> co.origins.stream())
            .filter(OriginRegistry::contains)
            .collect(Collectors.toList());
