    public boolean contains(Identifier originId, PlayerEntity playerEntity) {
        return conditionedOrigins
            .stream()
            .filter(co -> co.isConditionFulfilled(playerEntity))
            .flatMap(co -> co.origins().stream())
            .anyMatch(originId::equals);
    }

