import org.apache.logging.log4j.Logger;

public class Apoli implements ModInitializer, EntityComponentInitializer, OrderedResourceListenerInitializer {

	public static ApoliConfig config;

	public static MinecraftServer server;

	public static final Scheduler SCHEDULER = new Scheduler();

	public static final String MODID = "apoli";
	public static final Logger LOGGER = LogManager.getLogger(Apoli.class);
	public static String VERSION = "";
	public static int[] SEMVER;

	public static final AbilitySource LEGACY_POWER_SOURCE = Pal.getAbilitySource(Apoli.identifier("power_source"));

	public static final boolean PERFORM_VERSION_CHECK = false;

	@Override
	public void onInitialize() {
		ServerLifecycleEvents.SERVER_STARTED.register(s -> server = s);

		FabricLoader.getInstance().getModContainer(MODID).ifPresent(modContainer -> {
			VERSION = modContainer.getMetadata().getVersion().getFriendlyString();
			if(VERSION.contains("+")) {
				VERSION = VERSION.split("\\+")[0];
			}
			if(VERSION.contains("-")) {
				VERSION = VERSION.split("-")[0];
			}
			String[] splitVersion = VERSION.split("\\.");
			SEMVER = new int[splitVersion.length];
			for(int i = 0; i < SEMVER.length; i++) {
				SEMVER[i] = Integer.parseInt(splitVersion[i]);
			}
		});

		ModPacketsC2S.register();

		CommandRegistrationCallback.EVENT.register((dispatcher, registryAccess, environment) -> {
			PowerCommand.register(dispatcher);
			ResourceCommand.register(dispatcher);
		});

		Registry.register(Registries.RECIPE_SERIALIZER, Apoli.identifier("power_restricted"), PowerRestrictedCraftingRecipe.SERIALIZER);
		Registry.register(Registries.RECIPE_SERIALIZER, Apoli.identifier("modified"), ModifiedCraftingRecipe.SERIALIZER);

		Registry.register(Registries.LOOT_FUNCTION_TYPE, Apoli.identifier("add_power"), AddPowerLootFunction.TYPE);
		Registry.register(Registries.LOOT_FUNCTION_TYPE, Apoli.identifier("remove_power"), RemovePowerLootFunction.TYPE);

		Registry.register(Registries.LOOT_CONDITION_TYPE, Apoli.identifier("power"), PowerLootCondition.TYPE);

		ApoliClassData.registerAll();

		ModifierOperations.registerAll();

		PowerFactories.register();
		EntityConditions.register();
		BiEntityConditions.register();
		ItemConditions.register();
		BlockConditions.register();
		DamageConditions.register();
		FluidConditions.register();
		BiomeConditions.register();
		EntityActions.register();
		ItemActions.register();
		BlockActions.register();
		BiEntityActions.register();
		PowerIntegration.register();

		ResourceManagerHelper.get(ResourceType.SERVER_DATA).registerReloadListener(new GlobalPowerSetLoader());
		ResourceConditions.register(ApoliResourceConditions.ANY_NAMESPACE_LOADED, jsonObject -> ApoliResourceConditions.namespacesLoaded(jsonObject, PowerTypes.LOADED_NAMESPACES, false));
		ResourceConditions.register(ApoliResourceConditions.ALL_NAMESPACES_LOADED, jsonObject -> ApoliResourceConditions.namespacesLoaded(jsonObject, PowerTypes.LOADED_NAMESPACES, true));

		Criteria.register(GainedPowerCriterion.ID.toString(), GainedPowerCriterion.INSTANCE);

		LOGGER.info("Apoli " + VERSION + " has initialized. Ready to power up your game!");
	}

	public static Identifier identifier(String path) {
		return new Identifier(MODID, path);
	}

	@Override
	public void registerEntityComponentFactories(EntityComponentFactoryRegistry registry) {
		registry.beginRegistration(LivingEntity.class, PowerHolderComponent.KEY)
			.impl(PowerHolderComponentImpl.class)
			.respawnStrategy(RespawnCopyStrategy.ALWAYS_COPY)
			.end(PowerHolderComponentImpl::new);
	}

	@Override
	public void registerResourceListeners(OrderedResourceListenerManager manager) {
		manager.register(ResourceType.SERVER_DATA, new PowerTypes()).complete();
	}
}

package io.github.apace100.apoli.component;

import com.google.common.collect.Lists;
import dev.onyxstudios.cca.api.v3.component.ComponentKey;
import dev.onyxstudios.cca.api.v3.component.ComponentRegistry;
import dev.onyxstudios.cca.api.v3.component.sync.AutoSyncedComponent;
import dev.onyxstudios.cca.api.v3.component.tick.ServerTickingComponent;
import io.github.apace100.apoli.Apoli;
import io.github.apace100.apoli.integration.ModifyValueCallback;
import io.github.apace100.apoli.networking.packet.s2c.SyncPowerS2CPacket;
import io.github.apace100.apoli.networking.packet.s2c.SyncPowersInBulkS2CPacket;
import io.github.apace100.apoli.power.*;
import io.github.apace100.apoli.util.modifier.Modifier;
import io.github.apace100.apoli.util.modifier.ModifierUtil;
import net.fabricmc.fabric.api.networking.v1.PlayerLookup;
import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;
import net.minecraft.entity.Entity;
import net.minecraft.entity.LivingEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;

import java.util.*;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public interface PowerHolderComponent extends AutoSyncedComponent, ServerTickingComponent {

    ComponentKey<PowerHolderComponent> KEY = ComponentRegistry.getOrCreate(Apoli.identifier("powers"), PowerHolderComponent.class);

    void removePower(PowerType<?> powerType, Identifier source);

    int removeAllPowersFromSource(Identifier source);

    List<PowerType<?>> getPowersFromSource(Identifier source);

    boolean addPower(PowerType<?> powerType, Identifier source);

    boolean hasPower(PowerType<?> powerType);

    boolean hasPower(PowerType<?> powerType, Identifier source);

    <T extends Power> T getPower(PowerType<T> powerType);

    List<Power> getPowers();

    Set<PowerType<?>> getPowerTypes(boolean getSubPowerTypes);

    <T extends Power> List<T> getPowers(Class<T> powerClass);

    <T extends Power> List<T> getPowers(Class<T> powerClass, boolean includeInactive);

    List<Identifier> getSources(PowerType<?> powerType);

    void sync();

    static void sync(Entity entity) {
        KEY.sync(entity);
    }

    static void syncPower(Entity entity, PowerType<?> powerType) {

        if (entity == null || entity.getWorld().isClient) {
            return;
        }

        if (powerType instanceof PowerTypeReference<?> powerTypeRef) {
            powerType = powerTypeRef.getReferencedPowerType();
        }

        if (powerType == null) {
            return;
        }

        PowerHolderComponent component = PowerHolderComponent.KEY.getNullable(entity);
        if (component == null) {
            return;
        }

        NbtCompound powerData = new NbtCompound();
        Power power = component.getPower(powerType);

        if (power == null) {
            return;
        }

        powerData.put("Data", power.toTag(true));
        SyncPowerS2CPacket syncPowerPacket = new SyncPowerS2CPacket(entity.getId(), powerType.getIdentifier(), powerData);

        for (ServerPlayerEntity otherPlayer : PlayerLookup.tracking(entity)) {
            ServerPlayNetworking.send(otherPlayer, syncPowerPacket);
        }

        if (entity instanceof ServerPlayerEntity player) {
            ServerPlayNetworking.send(player, syncPowerPacket);
        }

    }

    static void syncPowers(Entity entity, Collection<? extends PowerType<?>> powerTypes) {

        if (entity == null || entity.getWorld().isClient || powerTypes.isEmpty()) {
            return;
        }

        PowerHolderComponent component = PowerHolderComponent.KEY.getNullable(entity);
        Map<Identifier, NbtElement> powersToSync = new HashMap<>();

        if (component == null) {
            return;
        }

        for (PowerType<?> powerType : powerTypes) {

            if (powerType instanceof PowerTypeReference<?> powerTypeRef) {
                powerType = powerTypeRef.getReferencedPowerType();
            }

            if (powerType == null) {
                continue;
            }

            Power power = component.getPower(powerType);
            if (power != null) {
                powersToSync.put(powerType.getIdentifier(), power.toTag(true));
            }

        }

        if (powersToSync.isEmpty()) {
            return;
        }

        SyncPowersInBulkS2CPacket syncPowersPacket = new SyncPowersInBulkS2CPacket(entity.getId(), powersToSync);
        for (ServerPlayerEntity otherPlayer : PlayerLookup.tracking(entity)) {

            if (ServerPlayNetworking.canSend(otherPlayer, SyncPowersInBulkS2CPacket.TYPE)) {
                ServerPlayNetworking.send(otherPlayer, syncPowersPacket);
            }

        }

        if (entity instanceof ServerPlayerEntity player && ServerPlayNetworking.canSend(player, SyncPowersInBulkS2CPacket.TYPE)) {
            ServerPlayNetworking.send(player, syncPowersPacket);
        }

    }

    static <T extends Power> void withPower(Entity entity, Class<T> powerClass, Predicate<T> power, Consumer<T> with) {
        if(entity instanceof LivingEntity) {
            Optional<T> optional = KEY.get(entity).getPowers(powerClass).stream().filter(p -> power == null || power.test(p)).findAny();
            optional.ifPresent(with);
        }
    }

    static <T extends Power> void withPowers(Entity entity, Class<T> powerClass, Predicate<T> filter, Consumer<T> with) {
        if(entity instanceof LivingEntity) {
            KEY.get(entity).getPowers(powerClass).stream().filter(p -> filter == null || filter.test(p)).forEach(with);
        }
    }

    static <T extends Power> List<T> getPowers(Entity entity, Class<T> powerClass) {
        return getPowers(entity, powerClass, false);
    }

    static <T extends Power> List<T> getPowers(Entity entity, Class<T> powerClass, boolean includeInactive) {
        return KEY.maybeGet(entity)
            .map(pc -> pc.getPowers(powerClass, includeInactive))
            .orElse(Lists.newArrayList());
    }

    static <T extends Power> boolean hasPower(Entity entity, Class<T> powerClass) {
        return hasPower(entity, powerClass, null);
    }

    static <T extends Power> boolean hasPower(Entity entity, Class<T> powerClass, Predicate<T> powerFilter) {
        if(entity instanceof LivingEntity) {
            return KEY.get(entity).getPowers().stream()
                .anyMatch(p -> powerClass.isAssignableFrom(p.getClass()) && p.isActive() &&
                    (powerFilter == null || powerFilter.test((T)p)));
        }
        return false;
    }

    static <T extends ValueModifyingPower> float modify(Entity entity, Class<T> powerClass, float baseValue) {
        return (float)modify(entity, powerClass, (double)baseValue, null, null);
    }

    static <T extends ValueModifyingPower> float modify(Entity entity, Class<T> powerClass, float baseValue, Predicate<T> powerFilter) {
        return (float)modify(entity, powerClass, (double)baseValue, powerFilter, null);
    }

    static <T extends ValueModifyingPower> float modify(Entity entity, Class<T> powerClass, float baseValue, Predicate<T> powerFilter, Consumer<T> powerAction) {
        return (float)modify(entity, powerClass, (double)baseValue, powerFilter, powerAction);
    }

    static <T extends ValueModifyingPower> double modify(Entity entity, Class<T> powerClass, double baseValue) {
        return modify(entity, powerClass, baseValue, null, null);
    }

    static <T extends ValueModifyingPower> double modify(Entity entity, Class<T> powerClass, double baseValue, Predicate<T> powerFilter, Consumer<T> powerAction) {
        if(entity instanceof LivingEntity living) {
            PowerHolderComponent powerHolder = PowerHolderComponent.KEY.get(entity);
            List<T> powers = powerHolder.getPowers(powerClass);
            List<Modifier> mps = powers.stream()
                .filter(p -> powerFilter == null || powerFilter.test(p))
                .flatMap(p -> p.getModifiers().stream()).collect(Collectors.toList());
            if(powerAction != null) {
                powers.stream().filter(p -> powerFilter == null || powerFilter.test(p)).forEach(powerAction);
            }

            powerHolder.getPowers(AttributeModifyTransferPower.class).stream()
                .filter(p -> p.doesApply(powerClass)).forEach(p -> p.addModifiers(mps));
            ModifyValueCallback.EVENT.invoker().collectModifiers(living, powerClass, baseValue, mps);
            return ModifierUtil.applyModifiers(entity, mps, baseValue);
        }
        return baseValue;
    }
}

package io.github.apace100.apoli.component;

import io.github.apace100.apoli.Apoli;
import io.github.apace100.apoli.power.*;
import io.github.apace100.apoli.util.GainedPowerCriterion;
import net.minecraft.entity.LivingEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.nbt.NbtList;
import net.minecraft.nbt.NbtString;
import net.minecraft.network.PacketByteBuf;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;
import org.jetbrains.annotations.NotNull;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public class PowerHolderComponentImpl implements PowerHolderComponent {

    private final LivingEntity owner;

    private final ConcurrentHashMap<PowerType<?>, Power> powers = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<PowerType<?>, List<Identifier>> powerSources = new ConcurrentHashMap<>();

    private final ConcurrentHashMap<PowerType<?>, Power> powersToRemove = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<PowerType<?>, Power> powersToAdd = new ConcurrentHashMap<>();

    public PowerHolderComponentImpl(LivingEntity owner) {
        this.owner = owner;
    }

    @Override
    public boolean hasPower(PowerType<?> powerType) {
        return powers.containsKey(powerType);
    }

    @Override
    public boolean hasPower(PowerType<?> powerType, Identifier source) {
        return powerSources.containsKey(powerType) && powerSources.get(powerType).contains(source);
    }

    @Override
    @SuppressWarnings("unchecked")
    public <T extends Power> T getPower(PowerType<T> powerType) {
        if(powers.containsKey(powerType)) {
            return (T)powers.get(powerType);
        }
        return null;
    }

    @Override
    public List<Power> getPowers() {
        return new LinkedList<>(powers.values());
    }

    public Set<PowerType<?>> getPowerTypes(boolean getSubPowerTypes) {
        return powers.keySet()
            .stream()
            .filter(pt -> getSubPowerTypes || !pt.isSubPower())
            .collect(Collectors.toCollection(HashSet::new));
    }

    @Override
    public <T extends Power> List<T> getPowers(Class<T> powerClass) {
        return getPowers(powerClass, false);
    }

    @Override
    @SuppressWarnings("unchecked")
    public <T extends Power> List<T> getPowers(Class<T> powerClass, boolean includeInactive) {
        List<T> list = new LinkedList<>();
        for(Power power : powers.values()) {
            if(powerClass.isAssignableFrom(power.getClass()) && (includeInactive || power.isActive())) {
                list.add((T)power);
            }
        }
        return list;
    }

    @Override
    public List<Identifier> getSources(PowerType<?> powerType) {
        if(powerSources.containsKey(powerType)) {
            return List.copyOf(powerSources.get(powerType));
        } else {
            return List.of();
        }
    }

    @Override
    public void removePower(PowerType<?> powerType, Identifier source) {
        this.removePower(powerType, source, true);
    }

    protected void removePower(PowerType<?> powerType, Identifier source, boolean root) {

        StringBuilder errorMessage= new StringBuilder("Cannot remove a non-existing power");
        if (powerType instanceof PowerTypeReference<?> powerTypeReference) {
            powerType = powerTypeReference.getReferencedPowerType();
            errorMessage.append(" (ID: \")").append(powerType.getIdentifier()).append("\")");
        }

        if (powerType == null) {
            Apoli.LOGGER.error(errorMessage.append(" from entity ").append(owner.getName().getString()));
            return;
        }

        if (!powerSources.containsKey(powerType)) {
            return;
        }

        List<Identifier> sources = powerSources.get(powerType);
        sources.remove(source);

        if (sources.isEmpty() && powers.containsKey(powerType)) {

            Power power = powers.get(powerType);
            powersToRemove.put(powerType, power);

            power.onRemoved();
            power.onRemoved(false);

            power.onLost();

        }

        if (powerType instanceof MultiplePowerType<?> multiplePowerType) {
            multiplePowerType.getSubPowers()
                .stream()
                .filter(PowerTypeRegistry::contains)
                .map(PowerTypeRegistry::get)
                .forEach(pt -> this.removePower(pt, source, false));
        }

        if (!root) {
            return;
        }

        powers.keySet().removeIf(powersToRemove::containsKey);
        powerSources.keySet().removeIf(powersToRemove::containsKey);

        powersToRemove.clear();

    }

    @Override
    public int removeAllPowersFromSource(Identifier source) {
        //noinspection MappingBeforeCount
        return (int) this.getPowersFromSource(source)
            .stream()
            .filter(Predicate.not(PowerType::isSubPower))
            .peek(pt -> this.removePower(pt, source))
            .count();
    }

    @Override
    public List<PowerType<?>> getPowersFromSource(Identifier source) {
        List<PowerType<?>> powers = new LinkedList<>();
        for(Map.Entry<PowerType<?>, List<Identifier>> sourceEntry : powerSources.entrySet()) {
            if(sourceEntry.getValue().contains(source)) {
                powers.add(sourceEntry.getKey());
            }
        }
        return powers;
    }

    @Override
    public boolean addPower(PowerType<?> powerType, Identifier source) {
        return this.addPower(powerType, source, true);
    }

    protected boolean addPower(PowerType<?> powerType, Identifier source, boolean root) {

        StringBuilder errorMessage = new StringBuilder("Cannot add a non-existing power");
        if (powerType instanceof PowerTypeReference<?> powerTypeRef) {
            powerType = powerTypeRef.getReferencedPowerType();
            errorMessage.append(" (ID: \"").append(powerTypeRef.getIdentifier()).append("\")");
        }

        if (powerType == null) {
            Apoli.LOGGER.error(errorMessage.append(" to entity ").append(owner.getName().getString()));
            return false;
        }

        List<Identifier> sources = powerSources.computeIfAbsent(powerType, pt -> new LinkedList<>());
        if (sources.contains(source)) {
            return false;
        }

        Power power = powerType.create(owner);
        sources.add(source);

        powerSources.put(powerType, sources);
        powers.put(powerType, power);

        powersToAdd.put(powerType, power);

        if (powerType instanceof MultiplePowerType<?> multiplePowerType) {
            multiplePowerType.getSubPowers()
                .stream()
                .filter(PowerTypeRegistry::contains)
                .map(PowerTypeRegistry::get)
                .forEach(pt -> this.addPower(pt, source, false));
        }

        if (!root) {
            return true;
        }

        Iterator<Map.Entry<PowerType<?>, Power>> addedIterator = powersToAdd.entrySet().iterator();
        while (addedIterator.hasNext()) {

            Map.Entry<PowerType<?>, Power> addedEntry = addedIterator.next();

            Power addedPower = addedEntry.getValue();
            addedIterator.remove();

            addedPower.onGained();

            addedPower.onAdded();
            addedPower.onAdded(false);

            if (owner instanceof ServerPlayerEntity player) {
                GainedPowerCriterion.INSTANCE.trigger(player, addedEntry.getKey());
            }

        }

        return true;

    }

    @Override
    public void serverTick() {
        this.getPowers(Power.class, true).stream().filter(p -> p.shouldTick() && (p.shouldTickWhenInactive() || p.isActive())).forEach(Power::tick);
    }

    @Override
    public void readFromNbt(@NotNull NbtCompound compoundTag) {
        this.fromTag(compoundTag, true);
    }

    protected void fromTag(NbtCompound compoundTag, boolean callPowerOnAdd) {

        if (owner == null) {
            Apoli.LOGGER.error("Owner was null in PowerHolderComponent#fromTag! This is not supposed to happen :(");
            return;
        }

        for (Power power : powers.values()) {

            if (callPowerOnAdd) {

                power.onRemoved();
                power.onLost();

            }

            power.onRemoved(!callPowerOnAdd);

        }

        powers.clear();
        NbtList powersTag = compoundTag.getList("Powers", NbtElement.COMPOUND_TYPE);
        for (int i = 0; i < powersTag.size(); i++) {

            NbtCompound powerTag = powersTag.getCompound(i);
            Identifier powerTypeId = Identifier.tryParse(powerTag.getString("Type"));

            if (powerTypeId == null || (callPowerOnAdd && PowerTypeRegistry.isDisabled(powerTypeId))) {
                continue;
            }

            List<Identifier> sources = new LinkedList<>();
            powerTag.getList("Sources", NbtElement.STRING_TYPE)
                .stream()
                .map(nbtElement -> Identifier.tryParse(nbtElement.asString()))
                .filter(Objects::nonNull)
                .forEach(sources::add);

            try {

                PowerType<?> powerType = PowerTypeRegistry.get(powerTypeId);
                Power power = powerType.create(owner);

                if (sources.isEmpty()) {
                    Apoli.LOGGER.warn("Power \"{}\" with missing sources found on entity {}! Skipping...", powerTypeId, owner.getName().getString());
                    continue;
                }

                powerSources.put(powerType, sources);

                try {
                    NbtElement powerData = powerTag.get("Data");
                    power.fromTag(powerData, !callPowerOnAdd);
                } catch (ClassCastException e) {
                    //  Occurs when the power was overridden by a data pack since last world load
                    //  where the overridden power now uses different data classes
                    Apoli.LOGGER.warn("Data type of power \"{}\" changed, skipping data for that power on entity {}", powerTypeId, owner.getName().getString());
                }

                powers.put(powerType, power);

                if (callPowerOnAdd) {
                    power.onAdded();
                }

                power.onAdded(!callPowerOnAdd);

            } catch (IllegalArgumentException e) {
                //  Occurs when the power is either not registered in the power registry,
                //  or the power no longer exists
                Apoli.LOGGER.warn("Unregistered power \"{}\" found on entity {}, skipping...", powerTypeId, owner.getName().getString());
            }

        }

        for (Map.Entry<PowerType<?>, List<Identifier>> entry : powerSources.entrySet()) {

            PowerType<?> powerType = entry.getKey();
            if (!(powerType instanceof MultiplePowerType<?> multiplePowerType)) {
                continue;
            }

            List<Identifier> subPowerIds = multiplePowerType.getSubPowers();
            for (Identifier subPowerId : subPowerIds) {
                try {

                    PowerType<?> subPowerType = PowerTypeRegistry.get(subPowerId);
                    for (Identifier source : entry.getValue()) {
                        addPower(subPowerType, source);
                    }

                } catch (IllegalArgumentException e) {
                    if (!(callPowerOnAdd && PowerTypeRegistry.isDisabled(subPowerId))) {
                        Apoli.LOGGER.warn("Multiple power \"{}\" (read from NBT data) contained unregistered sub-power: \"{}\"", powerType.getIdentifier(), subPowerId);
                    }
                }
            }

        }

    }

    @Override
    public void writeToNbt(@NotNull NbtCompound compoundTag) {
        this.toTag(compoundTag, false);
    }

    private void toTag(NbtCompound compoundTag, boolean onSync) {

        NbtList powersTag = new NbtList();
        for (Map.Entry<PowerType<?>, Power> entry : powers.entrySet()) {

            PowerType<?> power = entry.getKey();
            NbtCompound powerTag = new NbtCompound();

            if (!powerSources.containsKey(power) || powerSources.get(power).isEmpty()) {
                continue;
            }

            powerTag.putString("Factory", power.getFactory().getFactory().getSerializerId().toString());
            powerTag.putString("Type", power.getIdentifier().toString());
            powerTag.put("Data", entry.getValue().toTag(onSync));

            NbtList sourcesTag = new NbtList();
            powerSources.get(entry.getKey())
                .stream()
                .map(id -> NbtString.of(id.toString()))
                .forEach(sourcesTag::add);

            powerTag.put("Sources", sourcesTag);
            powersTag.add(powerTag);

        }

        compoundTag.put("Powers", powersTag);

    }

    @Override
    public void writeSyncPacket(PacketByteBuf buf, ServerPlayerEntity recipient) {

        NbtCompound compoundTag = new NbtCompound();
        this.toTag(compoundTag, true);

        buf.writeNbt(compoundTag);

    }

    @Override
    public void applySyncPacket(PacketByteBuf buf) {

        NbtCompound compoundTag = buf.readNbt();

        if (compoundTag != null) {
            this.fromTag(compoundTag, false);
        }

    }

    @Override
    public void sync() {
        PowerHolderComponent.sync(this.owner);
    }

    @Override
    public String toString() {
        StringBuilder str = new StringBuilder("PowerHolderComponent[\n");
        for (Map.Entry<PowerType<?>, Power> powerEntry : powers.entrySet()) {
            str.append("\t").append(PowerTypeRegistry.getId(powerEntry.getKey())).append(": ").append(powerEntry.getValue().toTag().toString()).append("\n");
        }
        str.append("]");
        return str.toString();
    }
}

