package io.github.apace100.apoli.power;

import com.google.gson.JsonObject;
import io.github.apace100.apoli.component.PowerHolderComponent;
import io.github.apace100.apoli.power.factory.PowerFactory;
import io.github.apace100.calio.data.SerializableDataTypes;
import net.minecraft.entity.Entity;
import net.minecraft.entity.LivingEntity;
import net.minecraft.text.MutableText;
import net.minecraft.text.Text;
import net.minecraft.util.Identifier;

public class PowerType<T extends Power> {

    private final PowerFactory<T>.Instance factory;
    private final Identifier identifier;

    private String nameTranslationKey;
    private String descriptionTranslationKey;

    private Text name;
    private Text description;

    private boolean hidden = false;
    private boolean subPower = false;

    public PowerType(Identifier id, PowerFactory<T>.Instance factory) {
        this.identifier = id;
        this.factory = factory;
    }

    public Identifier getIdentifier() {
        return identifier;
    }

    public PowerFactory<T>.Instance getFactory() {
        return factory;
    }

    public PowerType setHidden() {
        return this.setHidden(true);
    }

    public PowerType setSubPower() {
        return this.setSubPower(true);
    }

    public PowerType<?> setHidden(boolean hidden) {
        this.hidden = hidden;
        return this;
    }

    public PowerType<?> setSubPower(boolean subPower) {
        this.subPower = subPower;
        return this;
    }

    public void setTranslationKeys(String name, String description) {
        this.nameTranslationKey = name;
        this.descriptionTranslationKey = description;
    }

    public PowerType<?> setDisplayTexts(Text name, Text description) {

        this.name = name;
        this.description = description;

        return this;

    }

    public T create(LivingEntity entity) {

        T power = factory.apply(this, entity);

        power.setSerializableData(factory.getFactory().getSerializableData());
        power.setDataInstance(factory.getDataInstance());

        return power;

    }

    public boolean isHidden() {
        return this.hidden;
    }

    public boolean isSubPower() {
        return this.subPower;
    }

    public boolean isActive(Entity entity) {
        if(entity instanceof LivingEntity && identifier != null) {
            PowerHolderComponent component = PowerHolderComponent.KEY.get(entity);
            if(component.hasPower(this)) {
                return component.getPower(this).isActive();
            }
        }
        return false;
    }

    public T get(Entity entity) {
        if(entity instanceof LivingEntity) {
            PowerHolderComponent component = PowerHolderComponent.KEY.get(entity);
            return component.getPower(this);
        }
        return null;
    }

    public String getOrCreateNameTranslationKey() {
        if(nameTranslationKey == null || nameTranslationKey.isEmpty()) {
            nameTranslationKey =
                "power." + identifier.getNamespace() + "." + identifier.getPath() + ".name";
        }
        return nameTranslationKey;
    }

    public MutableText getName() {
        return name != null ? name.copy() : Text.translatable(getOrCreateNameTranslationKey());
    }

    public String getOrCreateDescriptionTranslationKey() {
        if(descriptionTranslationKey == null || descriptionTranslationKey.isEmpty()) {
            descriptionTranslationKey =
                "power." + identifier.getNamespace() + "." + identifier.getPath() + ".description";
        }
        return descriptionTranslationKey;
    }

    public MutableText getDescription() {
        return description != null ? description.copy() : Text.translatable(getOrCreateDescriptionTranslationKey());
    }

    public JsonObject toJson() {

        JsonObject jsonObject = factory.toJson();

        jsonObject.add("name", SerializableDataTypes.TEXT.write(getName()));
        jsonObject.add("description", SerializableDataTypes.TEXT.write(getDescription()));

        return jsonObject;

    }

    @Override
    public int hashCode() {
        return this.identifier.hashCode();
    }

    @Override
    public boolean equals(Object obj) {
        if(obj == this) {
            return true;
        }
        if(!(obj instanceof PowerType)) {
            return false;
        }
        Identifier id = ((PowerType)obj).getIdentifier();
        return identifier.equals(id);
    }
}

package io.github.apace100.apoli.power;

import io.github.apace100.apoli.integration.PowerClearCallback;
import net.minecraft.util.Identifier;
import org.jetbrains.annotations.Nullable;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.stream.Stream;

public class PowerTypeRegistry {

    private static final HashMap<Identifier, PowerType> idToPower = new HashMap<>();
    private static final Set<Identifier> disabledPowers = new HashSet<>();

    public static PowerType register(Identifier id, PowerType powerType) {
        if(idToPower.containsKey(id)) {
            throw new IllegalArgumentException("Duplicate power type id tried to register: '" + id.toString() + "'");
        }
        disabledPowers.remove(id);
        idToPower.put(id, powerType);
        return powerType;
    }

    protected static PowerType update(Identifier id, PowerType powerType) {
        if(idToPower.containsKey(id)) {
            PowerType old = idToPower.get(id);
            idToPower.remove(id);
        }
        return register(id, powerType);
    }

    protected static void disable(Identifier id) {
        remove(id);
        disabledPowers.add(id);
    }

    protected static void remove(Identifier id) {
        idToPower.remove(id);
    }

    public static boolean isDisabled(Identifier id) {
        return disabledPowers.contains(id);
    }

    public static int size() {
        return idToPower.size();
    }

    public static Stream<Identifier> identifiers() {
        return idToPower.keySet().stream();
    }

    public static Iterable<Map.Entry<Identifier, PowerType>> entries() {
        return idToPower.entrySet();
    }

    public static void forEach(BiConsumer<Identifier, PowerType<?>> powerTypeBiConsumer) {
        idToPower.forEach(powerTypeBiConsumer::accept);
    }

    public static Iterable<PowerType> values() {
        return idToPower.values();
    }

    @Nullable
    public static PowerType getNullable(Identifier id) {
        return idToPower.get(id);
    }

    public static PowerType get(Identifier id) {
        if(!idToPower.containsKey(id)) {
            throw new IllegalArgumentException("Could not get power type from id '" + id.toString() + "', as it was not registered!");
        }
        PowerType powerType = idToPower.get(id);
        return powerType;
    }

    public static Identifier getId(PowerType<?> powerType) {
        return powerType.getIdentifier();
    }

    public static boolean contains(Identifier id) {
        return idToPower.containsKey(id);
    }

    public static void clear() {
        PowerClearCallback.EVENT.invoker().onPowerClear();
        idToPower.clear();
    }

    public static void clearDisabledPowers() {
        disabledPowers.clear();
    }

    public static void reset() {
        clear();
        clearDisabledPowers();
    }
}

